// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Community".

I tried to work out the aspect of the homogeneity of the community versus
the heterogeneity of society and to represent it in this shader. To do this,
I defined an object (the result of a difference operation between a sphere
and a cube) that is multiplied by a kaleidoscopic iterative function system.

I use a function called soft minimum to represent as soft and considerate the
kind of interaction between members of a community that share the same goals
and often the same views, such as religious communities. The animation shows how
these objects connect and disconnect. This is intended to illustrate the dynamics
and intimacy between individual members.

And once again, all you can see is just a fragment shader that was coded on a
mobile phone.
*/

let theShader, dpr = 0.8*window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2445355/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext;
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; in vec2 aTexCoord; out vec2 vTexCoord;
void main() { vTexCoord = aTexCoord; vec4 positionVec4 = vec4(aPosition, 1.0);  
positionVec4.xy = positionVec4.xy * 2.0 - 1.0; gl_Position = positionVec4; }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T (20.+time)
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))

// Exponential smooth min for scalars
float sminq(float a, float b, float k) {
	k*=4.;
	float h=max(k-abs(a-b),.0)/k;
	return min(a,b)-h*h*k*.25;
}

// Smooth min for scalars
// which can be used as smooth union
// by making b and k negative.
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}

// Smooth min for 3D vectors
vec3 smin(vec3 a, vec3 b, float k) {
	vec3 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}

// Signed distance function of a box
float box(vec3 p, vec3 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z));
}

// Returns a psydo-random value for a given 2D vector
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}

// A kaleidoscopic iterated function system
// generates points in a fractal set
vec3 kifs(vec3 p) {
	float n=rnd(p.xz);
	for (int i=0; i<2; i++) {
		p.yz*=rot(T+rnd(vec2(i)));
		p.xy*=rot(-T*.2);
		p.xz*=rot(T+rnd(vec2(-i,i+1)));
		p=smin(p,-p,-1.);
		p-=vec3(1.8,.1,2.);
	}
	return p;
}

// Defines the scene you look at
// using the kifs fractal to generate
// multiple objects despite defining
// it only once
vec2 map(vec3 p) {
	vec3 q=kifs(p);
	float
	a=smin(box(q,vec3(.5))-.05, -(length(q)-.6),-.125),
	b=p.y+.5;

	// Adds a smooth gradient to the result
	// which can be used to smoothly transition
	// from the floor's color to the object's color
	float d = sminq(a, b, .25);

  return vec2(d, S(.05,.3, a-b));
}

// Returns the normal vector of the 
// surface at the given point
#define ZERO min(T,.0)
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).x+
		k.yxy*map(p+k.yxy*h).x+
		k.yyx*map(p+k.yyx*h).x+
		k.xxx*map(p+k.xxx*h).x
	);
}

// Returns the amount of shadow
// at the given point and the given
// light position
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=N(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i).x;
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,128.*d/i);
		i+=d;
	}
	return shd;
}

// Rotates the camera position
// to a fixed angle
void cam(inout vec3 p) {
	p.yz*=rot(.42);
}

// Defines the entry function of the shader
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-7),
	rd=N(vec3(uv,.2));
	cam(rd); cam(p);
	float dd=.0;
	for (float i=.0; i++<400.;) {
		vec2 d=map(p);
		if (d.x<1e-3) {
			vec3 n=norm(p),
			lp=vec3(-1,2,-3),
			l=N(lp-p);
			float
			dif=clamp(dot(l,n),.0,1.),
			shd=shadow(p+n*5e-2,lp),
			spe=clamp(dot(N(lp-rd),n),.0,1.),
			rfl=.35*pow(S(.0,1.,dot(reflect(rd,n),l)),6.);
			col+=.1+dif*shd*spe+rfl;
			col*=1.2*mix(vec3(1,.95,.8),vec3(.1,.3,.25),d.y);
			break;
		}
		if (d.x>5.) break;
		p+=rd*d.x;
		dd+=d.x;
	}
	// Adds some depth fog
	col=mix(vec3(0),col,exp(-125e-5*dd*dd*dd));
	col*=1.-.01*dot(p,p);
	col+=sin(FC.x*114.0)*sin(FC.y*211.1)/512.0;
	col=max(col,.04);
	O=vec4(col,1);
}

